"""Eight original extrapulmonary sarcoidosis questions."""
from create_rheum_sarcoid_diagnosis import rows,q,D,T,ref
CA=ref('AHA cardiac sarcoidosis scientific statement: 2024','https://doi.org/10.1161/CIR.0000000000001240')
NE=ref('Neurosarcoidosis Consortium diagnostic consensus','https://doi.org/10.1001/jamaneurol.2018.2295')

q('A sarcoidosis patient has hypercalcemia, suppressed PTH and increased 1,25-dihydroxyvitamin D. What is the most likely mechanism?', 'Extrarenal macrophage 1-alpha-hydroxylase activity in granulomatous inflammation',[
 ('Autonomous parathyroid hormone secretion','The suppressed PTH argues against a PTH-driven mechanism.'),('Loss of all vitamin D activation','This would not explain elevated calcitriol.'),('PTH receptor resistance as the sole mechanism','This does not explain the stated granulomatous calcitriol pattern.')],
 'Granulomatous calcitriol production escapes normal regulation','**Activated macrophages can increase calcitriol production and intestinal calcium absorption.**',['Hypercalciuria may occur with or without overt hypercalcemia.','Malignancy, primary hyperparathyroidism and other causes still require consideration when the pattern differs.'], '**Assess calcium severity, renal function and supplement exposure.**',['Provide appropriate hydration and disease-directed treatment when indicated.','Avoid unreviewed high-dose vitamin D or calcium supplementation.'],[['PTH','Usually suppressed'],['Calcitriol','Can be elevated'],['Kidney','Stones or renal injury possible']],[D],style='clinical_scenario')

q('A patient with systemic granulomatous disease has chronic meningitis, cranial neuropathies and a compatible contrast MRI. Extraneural biopsy confirms sarcoidosis after mimics are excluded. Which consensus category is generally supported?', 'Probable neurosarcoidosis',[
 ('Definite neurosarcoidosis solely from the extraneural biopsy','Definite classification requires compatible nervous-system tissue evidence.'),('Possible neurosarcoidosis with no histological evidence anywhere','Extraneural histological confirmation supports the probable category.'),('A definitive exclusion of neurosarcoidosis because neural tissue was not sampled','A safer extraneural biopsy can support the diagnosis when neural biopsy is unsafe.')],
 'Diagnostic confidence reflects the site and quality of evidence','**A compatible neurological syndrome plus systemic tissue confirmation can support probable neurosarcoidosis.**',['Neural biopsy supports definite disease when feasible and appropriate.','TB, fungi, malignancy and other inflammatory causes of meningitis need careful exclusion.'], '**Avoid dangerous neural sampling when a safer informative site is available.**',['Use CSF and imaging to characterize the syndrome and alternatives.','Treatment urgency depends on the neurological threat.'],[['Possible','Compatible syndrome without tissue confirmation'],['Probable','Systemic tissue evidence'],['Definite','Nervous-system tissue evidence']],[NE],style='clinical_scenario')

q('Parotid swelling, uveitis, fever and facial nerve palsy most strongly suggest which sarcoid syndrome?', 'Heerfordt syndrome',[
 ('Lofgren syndrome','This is the hilar adenopathy/erythema nodosum/ankle inflammatory constellation.'),('Melkersson–Rosenthal syndrome','Facial palsy and swelling can overlap, but uveoparotid sarcoid features support Heerfordt.'),('Ramsay Hunt syndrome','Otic zoster and its characteristic painful vesicular context would be more suggestive.')],
 'Recognize the uveoparotid pattern','**Heerfordt syndrome combines salivary, ocular and cranial-nerve manifestations.**',['Incomplete presentations can occur.','Facial weakness still requires examination for alternative neurological and infectious causes.'], '**Assess the eye and nervous system promptly.**',['Use appropriate systemic sarcoid confirmation when needed.','Do not treat facial palsy as an isolated idiopathic event when the systemic pattern is present.'],[['Parotid/uveitis','Characteristic clue'],['Facial nerve','Cranial neuropathy'],['Systemic assessment','Connects the findings']],[D,NE],style='clinical_scenario')

q('Which ocular complication can occur in sarcoidosis and threaten vision?', 'Uveitis',[
 ('A refractive error as the defining inflammatory lesion','Refraction does not explain ocular inflammation.'),('Age-related presbyopia as evidence of active sarcoid','This is not a sarcoid-specific inflammatory complication.'),('Subconjunctival hemorrhage as the only relevant eye manifestation','Sarcoid can involve deeper ocular structures.')],
 'Do not restrict eye assessment to symptomatic dryness','**Sarcoid uveitis can affect vision and can sometimes be initially subtle.**',['ATS suggests baseline eye assessment even without ocular symptoms in established sarcoidosis.','Pain, photophobia, floaters or visual change require timely ophthalmological evaluation.'], '**Treat according to the involved ocular compartment and severity.**',['Topical treatment may suit some anterior disease; posterior or severe disease can require systemic therapy.','Exclude infectious mimics before immune treatment.'],[['Uveitis','Potential visual threat'],['Baseline assessment','Can detect silent involvement'],['Symptoms','Require prompt review']],[D,T])

q('A 46-year-old with known sarcoidosis has syncope and new high-grade AV block. Which complication is most urgent to assess?', 'Cardiac sarcoidosis',[
 ('Benign vasovagal syncope as certain','High-grade conduction disease is an important cardiac warning sign.'),('Simple anxiety-related hyperventilation','This does not explain objective AV block.'),('Isolated pleuritis','This does not account for the conduction abnormality.')],
 'Conduction disease can signal myocardial granulomatous involvement','**Unexplained AV block, ventricular arrhythmia or ventricular dysfunction should raise concern for cardiac sarcoidosis.**',['A normal pulmonary symptom burden does not exclude heart involvement.','Other myocarditis, ischemic and infiltrative causes must also be assessed.'], '**Stabilize the rhythm and pursue specialist cardiac evaluation.**',['CMR and FDG-PET provide complementary information.','Device and sudden-death risk decisions are not replaced by immunosuppression alone.'],[['AV block','Important warning'],['VT or dysfunction','Additional major phenotypes'],['Management','Rhythm/device plus inflammatory assessment']],[CA],style='clinical_scenario')

q('Which statement best describes CMR and FDG-PET in cardiac sarcoidosis?', 'CMR characterizes myocardial injury/scar and PET can assess inflammatory activity; they are complementary and neither is universally definitive alone',[
 ('CMR late enhancement uniquely proves sarcoid rather than any other myocarditis','LGE patterns require clinical and differential interpretation.'),('Diffuse FDG uptake always proves active sarcoid regardless of preparation','Inadequate physiological myocardial suppression can make PET misleading.'),('A negative unguided endomyocardial biopsy excludes disease','Patchy involvement reduces biopsy sensitivity.')],
 'Use multimodality evidence rather than a single imperfect test','**Cardiac sarcoidosis can be patchy and no one test is perfect.**',['Appropriate PET preparation is important.','Imaging-guided or electroanatomic-guided biopsy can improve yield in selected cases.'], '**Interpret the tests with the presenting syndrome and alternatives.**',['Biopsy may be important when imaging is inconclusive or giant-cell myocarditis is a concern.','Do not assume all late enhancement represents currently reversible inflammation.'],[['CMR','Injury and scar assessment'],['PET','Inflammatory activity with proper preparation'],['Biopsy','Specific when positive; sampling limits when negative']],[CA,ref('Cardiac sarcoidosis diagnostic approach: 2026','https://doi.org/10.1161/CIRCULATIONAHA.126.079275')])

q('A patient with sarcoidosis has hepatomegaly and a predominantly alkaline-phosphatase elevation. Which mechanism deserves consideration?', 'Granulomatous hepatic involvement',[
 ('Isolated muscle injury as the usual source of marked cholestatic enzyme elevation','Muscle injury primarily affects enzymes such as AST/ALT and CK rather than a cholestatic pattern.'),('Autoimmune hemolysis as the sole explanation','Hemolysis produces a different biochemical pattern.'),('A normal variant proven without biliary or medication assessment','Cholestasis requires an appropriate differential.')],
 'Hepatic sarcoid often has a cholestatic biochemical pattern','**Granulomatous liver involvement can raise alkaline phosphatase and produce hepatomegaly.**',['Biliary obstruction, drug injury, infection and other cholestatic disorders must be considered.','Not every asymptomatic biochemical abnormality requires aggressive systemic treatment.'], '**Assess severity and complications.**',['Portal hypertension and chronic liver damage can occur in selected patients.','Treatment decisions depend on symptoms, cholestasis and organ risk rather than biopsy granulomas alone.'],[['Pattern','Often cholestatic'],['Differential','Obstruction, drugs and other liver disease'],['Treatment','Severity and organ-risk based']],[D,T],style='clinical_scenario')

q('Which renal lesion can occur directly in sarcoidosis in addition to calcium-related stones or injury?', 'Granulomatous tubulointerstitial nephritis',[
 ('Anti-GBM nephritis as the defining universal lesion','This is a separate antibody-mediated process.'),('Pauci-immune crescentic GN as the required sarcoid pattern','This more strongly suggests a different small-vessel process.'),('Diabetic nodular sclerosis solely from granuloma formation','This is not the characteristic direct sarcoid renal lesion.')],
 'Separate granulomatous renal disease from calcium-mediated damage','**Sarcoid can involve the interstitium directly.**',['Hypercalcemia, nephrocalcinosis, medications and unrelated kidney disease remain alternatives.','Granulomatous interstitial nephritis also has infectious and drug-related causes.'], '**Assess kidney function, urine, calcium and the need for biopsy.**',['Exclude relevant mimics before attributing a granuloma to sarcoid.','Prompt treatment of active renal inflammation can preserve function.'],[['Direct lesion','Granulomatous interstitial nephritis'],['Indirect injury','Calcium-related mechanisms'],['Biopsy context','Exclude drugs and infection']],[D,T])

if __name__=='__main__':print(f'Sarcoidosis cumulative draft: {len(rows)} questions')
